<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000;

struct Edge {
    int to, rev, cap;
};

vector<Edge> G[MAXN];

char A[15][15], B[15][15];
int id[15][15], cnt;
int S, T, limitT, n, zx, zy;
int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};

inline bool inside(int x, int y) {
    return x >= 0 && y >= 0 && x < n && y < n && A[x][y] >= '0' && A[x][y] <= '9';
}

void addEdge(int u, int v, int c) {
    int ui = (int)G[u].size();
    int vi = (int)G[v].size();
    G[u].push_back({v, vi, c});
    G[v].push_back({u, ui, 0});
}

void buildNetwork(int sx, int sy) {
    if (B[sx][sy] != 0) {
        addEdge(id[sx][sy] + cnt, T, B[sx][sy] - '0');
    }
    if (A[sx][sy] == '0') return;
    addEdge(S, id[sx][sy], A[sx][sy] - '0');
    if (B[sx][sy] != 0) {
        addEdge(id[sx][sy], id[sx][sy] + cnt, 10);
    }

    int d1[15][15], d2[15][15];
    memset(d1, -1, sizeof(d1));
    memset(d2, -1, sizeof(d2));

    queue<pair<int,int>> qa, qb;
    qa.push({sx, sy});
    qb.push({zx, zy});
    d1[sx][sy] = 0;
    d2[zx][zy] = 0;

    while (!qa.empty()) {
        int layer = (int)qa.size();
        while (layer--) {
            int x = qa.front().first;
            int y = qa.front().second;
            qa.pop();

            if (d2[x][y] >= 0) continue;

            for (int i = 0; i < 4; ++i) {
                int nx = x + dx[i];
                int ny = y + dy[i];
                if (inside(nx, ny) && d1[nx][ny] < 0) {
                    d1[nx][ny] = d1[x][y] + 1;
                    if (d1[nx][ny] > limitT) break;
                    if (d2[nx][ny] >= 0) continue;
                    qa.push({nx, ny});
                    if (B[nx][ny] != '0') {
                        addEdge(id[sx][sy], id[nx][ny] + cnt, 10);
                    }
                }
            }
        }

        layer = (int)qb.size();
        while (layer--) {
            int x = qb.front().first;
            int y = qb.front().second;
            qb.pop();

            for (int i = 0; i < 4; ++i) {
                int nx = x + dx[i];
                int ny = y + dy[i];
                if (inside(nx, ny) && d2[nx][ny] < 0) {
                    d2[nx][ny] = d2[x][y] + 1;
                    qb.push({nx, ny});
                }
            }
        }
    }
}

int level[MAXN], ptr[MAXN];

bool bfsLevel() {
    fill(level, level + T + 1, -1);
    queue<int> q;
    level[S] = 0;
    q.push(S);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int i = 0; i < (int)G[u].size(); ++i) {
            Edge &e = G[u][i];
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[T] != -1;
}

int dfs(int u, int f) {
    if (u == T) return f;

    for (int &i = ptr[u]; i < (int)G[u].size(); ++i) {
        Edge &e = G[u][i];
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int pushed = dfs(e.to, min(f, e.cap));
            if (pushed) {
                e.cap -= pushed;
                G[e.to][e.rev].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int ans = 0;
    while (bfsLevel()) {
        fill(ptr, ptr + T + 1, 0);
        while (int pushed = dfs(S, 10000000)) ans += pushed;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> limitT;
    for (int i = 0; i < n; ++i) cin >> A[i];
    for (int i = 0; i < n; ++i) cin >> B[i];

    memset(id, -1, sizeof(id));
    cnt = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (A[i][j] == 'Z') {
                zx = i;
                zy = j;
            } else if (inside(i, j)) {
                id[i][j] = ++cnt;
            }
        }
    }

    S = 0;
    T = 2 * cnt + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (inside(i, j)) buildNetwork(i, j);
        }
    }

    cout << maxFlow() << '\n';
    return 0;
}
